INSERT INTO public.chronicles_books(id,title,description,primary_writer,collaboration,language) VALUES ('ab7a1070-1966-4996-8026-000000000101','THE LAST HOUR','Main English project · Proposal · Three timelines, one phone line. Story bible v1 by Claude. No chapters drafted.','Benji','solo','en') ON CONFLICT(id) DO NOTHING;
INSERT INTO public.chronicles_book_entries(book_id,kind,title,body,updated_by) SELECT 'ab7a1070-1966-4996-8026-000000000101','rules','Book Rules','
  <h2>Writing rules</h2>
  <div class="rule"><b>01</b><div>Every chapter opens with place + date. Three times, three dates, never blurred.</div></div>
  <div class="rule"><b>02</b><div>One object per time: paper cup with a skin (1966) · county flashlight (1996) · evidence bag (2026). Objects don''t cross timelines until a twist needs them to.</div></div>
  <div class="rule"><b>03</b><div>One light per time: studio red + fluorescent · a flashlight in a dead building · evidence-room white.</div></div>
  <div class="rule"><b>04</b><div>Chapters 1–3: callers only. The woman does not appear until the reader loves at least two of them.</div></div>
  <div class="rule"><b>05</b><div>The woman is never described by voice until twist 4 — only by her words. The reader has to be able to merge two women into one.</div></div>
  <div class="rule"><b>06</b><div>Nobody knows the future. They know files. If a character predicts something that isn''t in a file, that''s a mistake.</div></div>
  <div class="rule"><b>07</b><div>Short declaratives. No adverbs. Dialogue does the work. Kent Haruf, Denis Johnson — not a podcast.</div></div>
  <div class="rule"><b>08</b><div>Don''t invent a date for an unknown day. Leave it unknown.</div></div>
  <div class="rule"><b>09</b><div>Written chapters and proposed events are two different states. This page is 100% proposed.</div></div>
','Benji' WHERE NOT EXISTS(SELECT 1 FROM public.chronicles_book_entries WHERE book_id='ab7a1070-1966-4996-8026-000000000101' AND kind='rules');
INSERT INTO public.chronicles_dsl_projects(book_id,updated_by,change_note) VALUES('ab7a1070-1966-4996-8026-000000000101','Benji','Create separate THE LAST HOUR proposal') ON CONFLICT(book_id) DO NOTHING;
INSERT INTO public.chronicles_dsl_branches(book_id,name,data,updated_by,change_note) SELECT 'ab7a1070-1966-4996-8026-000000000101','Story bible v1 · Proposal','{"schema":1,"template":{"id":"DSL-T001","revision":2},"title":"THE LAST HOUR","summary":"Brief Every night at midnight, Hal Wesley opens the phone lines and lets Las Vegas talk. Cab drivers, cocktail waitresses, a retired pit boss who can''t stand being home. He plays their songs. He writes two words under every name. Then a woman calls. She doesn''t want a song. She says one thing about the caller before her — and that caller''s life changes. She calls every night. She knows what''s in his shirt pocket. She knows about the storage unit in Reno. She has read every legal pad he ever filled — pads that are still in his trunk. She is Detective Nora Reyes, 1996, sitting in the dead KDUS building three weeks before it''s demolished, with his boxes open and the studio phone in her hand. And in 2026, Detective Jo Hadley has a rotary phone in an evidence bag, two cold files from the same address — a host who vanished in ''66, a detective who vanished in ''96 — and a phone that rings when it isn''t plugged into anything. Nobody on the line knows the future. They know the files. And every warning rewrites the files in front of them.","rules":"Writing rules 01Every chapter opens with place + date. Three times, three dates, never blurred. 02One object per time: paper cup with a skin (1966) · county flashlight (1996) · evidence bag (2026). Objects don''t cross timelines until a twist needs them to. 03One light per time: studio red + fluorescent · a flashlight in a dead building · evidence-room white. 04Chapters 1–3: callers only. The woman does not appear until the reader loves at least two of them. 05The woman is never described by voice until twist 4 — only by her words. The reader has to be able to merge two women into one. 06Nobody knows the future. They know files. If a character predicts something that isn''t in a file, that''s a mistake. 07Short declaratives. No adverbs. Dialogue does the work. Kent Haruf, Denis Johnson — not a podcast. 08Don''t invent a date for an unknown day. Leave it unknown. 09Written chapters and proposed events are two different states. This page is 100% proposed.","hypothesis":"","foundation":{"language":"en","genre":"American mystery · analog horror","theme":"","audience":"Adult, quiet voice; accessible audio chapters and a contemporary entry point.","centralConflict":"Every warning changes the evidence. Hal must decide what saving Danny will cost; Nora and Jo investigate histories that include themselves.","stakes":"","narrativePromise":"","startingApproach":"premise","complexity":"layered","collaboration":"solo"},"world":{"locations":"Las Vegas, Industrial Road, Boulder Highway, Lake Mead, Henderson","historicalNotes":"Real events used as furniture 11 Jun 1938 — Hugh Lord, last resident of St. Thomas, Nevada, rows away as Lake Mead reaches his house. The town goes under. (The lake is where the men are sent. The town is what''s down there.) 1960s — Nevada Test Site underground shots 65 miles north; Vegas hotels sway. Callers mention the shaking. Thanksgiving 1966 — Howard Hughes arrives by train, carried into the Desert Inn on a stretcher, starts buying the Strip. Hal vanishes the same week. 26 Nov 1996 — the Sands is imploded. Vegas is tearing down the sixties. Nora''s building is next. May 2022 — human remains in a barrel surface at Hemenway Harbor as Lake Mead drops; more follow. Cold cases reopen. Jo gets hired. 2022–2026 — record lows; St. Thomas fully walkable. verify at research pass Rule: real events are mentioned by callers, on a bar TV, in a headline. Never explained. Never the plot. Historical and procedural claims await research verification.","technology":"AM radio, legal pads, reel tapes, rotary telephone, voice memos","hardRules":"How the phone works · the triangle Nora (1996) → Hal (1966). She dials the old on-air number out of habit — a cop tries every number in a file. He picks up live. Night one she thinks it''s a prank. Night three she knows. Jo (2026) ← Nora (1996). Jo''s evidence-bag phone rings, plugged into nothing. \"Is this the station?\" It''s Nora, dialing the same handset thirty years earlier. Jo says yes because she doesn''t know what else to say. Hal hears Nora — and some nights Jo. Two women. Hal and the reader hear one. Jo knows things Nora can''t — she''s read Nora''s notes on Hal. Nobody hears everyone. Each woman thinks she is the only future. The rule. Nobody knows the future. They know the files. Change a life → change what''s left → the box changes. Nora is reading a book that rewrites itself every time she speaks. \"You''ve read my pads.\" — \"Every one.\" — \"They''re in my car.\" — \"They''re in a box.\"","exceptions":"Routing, memory and file changes remain unresolved proposals."},"characters":[{"id":"lh-life-1","name":"Hal Wesley","aliases":["Hal"],"role":"the host","ageNote":"Hal Wesley, 34","biography":"Host, \"The Last Hour,\" KDUS 1340 AM, midnight–4, six nights.\nFrom Bakersfield. Came in ''61 after a divorce he never mentions.\nBlack coffee in a paper cup until a skin forms. Yellow legal pad: name, two words.\nHelps strangers at 2 AM; lets his sister''s storage unit in Reno sit a year.\nKeeps every pad. Fifty of them, in the trunk of a ''59 Impala.\nSign-on: \"If you''re still working, God bless you. If you''re done and can''t shut it off — stay a while.\"\nFate: vanishes at Lake Mead, 23 Nov 1966. By choice. (Reader learns \"by choice\" last.)","relationships":""},{"id":"lh-life-2","name":"Sam Pruitt","aliases":["Sam"],"role":"producer · screener","ageNote":"Sam Pruitt, 41","biography":"Ex-Army radio operator, Korea. Knows what a lying voice sounds like.\nTwo fingers through the glass. Crosses out callers he doesn''t like — twice if he really doesn''t.\nWants the show on the clock. Hal always runs long.\nSecret: he hears what the woman is before Hal does. Lets her through anyway. Last sheet in the box: \"It''s her again. Let her through.\"\nDies 1994, Henderson. His widow Dot gives the county four boxes from the garage.","relationships":"Husband of Dot Pruitt."},{"id":"lh-life-3","name":"Nora Reyes","aliases":["Nora"],"role":"detective · the voice","ageNote":"Nora Reyes, 30","biography":"LVMPD cold case, two years in. Patrol before that.\nOfficially: close the Industrial Road file before demolition. Really: find her mother.\nDials every number in every file. Can''t leave a phone unrung.\nObjects: county flashlight, the black studio phone, her mother''s missing-person flyer folded in her badge wallet.\nVoice: clipped, cop-flat — until night three, when it isn''t.\nSecret: daughter of Carol Mendez (missing Dec 1966) and Tony Reyes, Stardust dealer. Born 1966. She is in the files she''s reading.\nFate: last seen entering 2201 Industrial Road, 18 Dec 1996. Demolished 19 Dec.","relationships":"Daughter of Carol Mendez and Tony Reyes; chronology unresolved."},{"id":"lh-life-4","name":"Jo Hadley","aliases":["Jo"],"role":"detective · the reader''s eyes","ageNote":"Jo Hadley, 26","biography":"LVMPD cold case, Lake Mead unit. Youngest in the room. Records everything as voice memos because she doesn''t trust her own handwriting.\nGranddaughter of Danny Hadley — the electrician who went to the lake in 1966 and came back. Her great-grandmother Ruth''s voice is the first tape she plays.\nBelieves paper. Has to unlearn it.\nObjects: rotary phone in an evidence bag; a charger she keeps reaching for on a phone with no port.\nVoice: dry, tired, says \"okay\" a lot. The only person in the book who sounds like now.\nSecret: she exists because Hal went to the lake. Warn him off, unmake her grandfather. She figures it out before she tells him. Tells him anyway.","relationships":"Granddaughter of Danny Hadley; great-granddaughter of Ruth Hadley."},{"id":"lh-life-5","name":"Ruth Hadley","aliases":["Ruth"],"role":"caller · the mother","ageNote":"Ruth Hadley, 58","biography":"Cocktail waitress, the Fremont, graveyard.\nCalls 2 Nov 1966, 1:40 AM, from the payphone at the end of the bar. Slot machines behind her. A roll of dimes.\n\"Twenty-seven days.\" Two calls home from her son: I''m here. Then: the site changed, we''re closer to the water now. She didn''t catch the name. She was asking if he''d eaten.\n\"I don''t want anyone in trouble. I want him to call me.\"\nFate: Danny comes home in December. She never knows why. Listens to the show for years after it''s gone, to static.","relationships":"Mother of Danny Hadley."},{"id":"lh-life-6","name":"Danny Hadley","aliases":["Danny"],"role":"the missing son","ageNote":"Danny Hadley, 26","biography":"Electrician. Navy, two years, Subic Bay.\nHired off Boulder Highway: \"resort maintenance at the lake.\" Cash. No paperwork.\nFate: comes back. Never talks about it. Raises a family in Henderson. Dies 2019. His granddaughter is Jo.","relationships":"Son of Ruth Hadley; grandfather of Jo Hadley."},{"id":"lh-life-7","name":"Lenny Kostas","aliases":["Lenny"],"role":"regular caller","ageNote":"Lenny Kostas, 44","biography":"Cab driver, Yellow-Checker, nights. Wife Dolores sews with the radio on.\nAnniversary call: \"Tell her I remembered.\" — \"Tell her yourself, she''s listening.\" — \"Honey. One o''clock. Don''t wait up.\"\nFate: the woman''s first warning sends him down Fremont instead of Boulder Highway. He lives. Never knows why he changed routes. Calls every anniversary until the station goes dark in ''79.","relationships":""},{"id":"lh-life-8","name":"Carol Mendez","aliases":["Carol"],"role":"regular caller · Nora''s mother","ageNote":"Carol Mendez, 24","biography":"Cocktail waitress, the Mint. Offered a dealer job at the Stardust — graveyard, better money. Father says no \"because I said.\"\nHal catches himself siding with the father. Corrects it on air.\nFate: takes the job. Meets Tony Reyes. Pregnant by spring. Vanishes 14 Dec 1966, Stardust employee lot.","relationships":"Mother of Nora Reyes; chronology unresolved."},{"id":"lh-life-9","name":"Earl Vance","aliases":["Earl"],"role":"regular caller · the untouched life","ageNote":"Earl Vance, 63","biography":"Retired pit boss, Golden Nugget, one month out. Wife can''t stand him home.\n\"What are you in a hurry for at 6 AM?\" — \"That''s the thing I can''t answer.\"\nDedicates \"Unforgettable.\"\nFate: nothing happens to him. The line never touches him. The reader needs one of those.","relationships":""},{"id":"lh-life-10","name":"Sal Kessler","aliases":["Sal"],"role":"the front","ageNote":"Sal Kessler, 50","biography":"Runs the day-labor office on Boulder Highway. Cash jobs. Men nobody files a report for.\nTakes money and instructions from a man in a brown coat who leaves no number.\nDoesn''t ask where the men go. That''s the crime.","relationships":""},{"id":"lh-life-11","name":"Deputy Wade Brandt","aliases":["Deputy"],"role":"the cop who closed it","ageNote":"Deputy Wade Brandt, 28 → 88","biography":"1966: took Ruth''s report. Closed it \"voluntary departure\" in nine days.\n2026: Boulder City, oxygen tank, sharp. Tells Jo the one thing nobody wrote down: \"There was a woman calling that station every night. We traced it. The number didn''t exist.\"","relationships":""},{"id":"lh-life-12","name":"Dot Pruitt","aliases":["Dot"],"role":"the widow","ageNote":"Dot Pruitt","biography":"Gives the county four boxes from Sam''s garage. \"He said somebody would come for them. He didn''t say when.\"","relationships":"Widow of Sam Pruitt."}],"events":[{"id":"lh-night-1","title":"Earl, Carol, Lenny, the recipe lady — and a man crossed out twice","summary":"Earl, Carol, Lenny, the recipe lady — and a man crossed out twice Four warm calls. The formula lands.Fifth caller won''t give his name, asked for Hal by a middle name he never uses on air. One sentence: \"Don''t go to the lake, Hal.\" Dial tone. Hal laughs. Sam doesn''t.Close: note from Sam — your sister called, Reno, storage unit. Hal writes a time on the back, crosses it out. Ask her first.","date":"1966-10-28","year":1966,"precision":"day","dateLabel":"Las Vegas · 28 Oct 1966 · ch 1","order":1,"type":"event","status":"proposal","location":"Las Vegas","characters":"Hal Wesley, Sam Pruitt, Earl Vance, Carol Mendez, Lenny Kostas","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-2","title":"Ruth Hadley — \"Twenty-seven days\"","summary":"Ruth Hadley — \"Twenty-seven days\" Office name and address off-air. \"We don''t pull people out of their homes on an accusation we know nothing about.\"A later caller recognizes the Boulder Highway office: \"the destination was always going to change.\"Hal doesn''t go home after.","date":"1966-11-02","year":1966,"precision":"day","dateLabel":"Las Vegas · 2 Nov 1966 · ch 2","order":2,"type":"event","status":"proposal","location":"Las Vegas","characters":"Hal Wesley, Ruth Hadley","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-3","title":"The woman — night one","summary":"The woman — night one Lenny hangs up. New caller, a woman. No song. \"Tell him not to take Boulder Highway tonight.\"Hal relays it as a joke. Lenny takes Fremont.1:10 AM: a cab is hit head-on on Boulder Highway. Driver Ray Dunning, 38, dead. Lenny is alive. Somebody else isn''t. Nobody''s hands are clean after night one.","date":"1966-11-04","year":1966,"precision":"day","dateLabel":"Las Vegas · 4 Nov 1966 · ch 3","order":3,"type":"event","status":"proposal","location":"Las Vegas","characters":"Hal Wesley, Nora Reyes, Lenny Kostas","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-4","title":"Nora opens the boxes","summary":"Nora opens the boxes The Sands came down last night; the whole town smells like concrete dust. Demolition order for 2201 Industrial Road: 19 Dec.Four boxes. Fifty legal pads. Reel-to-reel. Sam''s call sheets with crossings-out.She plays the first tape. Ruth Hadley''s voice. Slot machines.The studio phone is still on the desk. She lifts it. There''s a tone.","date":"1996-11-27","year":1996,"precision":"day","dateLabel":"Las Vegas · 27 Nov 1996 · ch 4","order":4,"type":"event","status":"proposal","location":"Las Vegas","characters":"Nora Reyes, Ruth Hadley","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-5","title":"Night four — Carol","summary":"Night four — Carol Carol calls: she''s taking the Stardust job Monday.The woman, after: \"Carol shouldn''t take that job.\" Hal doesn''t relay it. Felt like meddling.Sam, through the glass, writes a word on the sheet and underlines it.","date":"1966-11-07","year":1966,"precision":"day","dateLabel":"Las Vegas · 7 Nov 1966 · ch 5","order":5,"type":"event","status":"proposal","location":"Las Vegas","characters":"Hal Wesley, Nora Reyes, Carol Mendez, Sam Pruitt","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-6","title":"The file that wasn''t there","summary":"The file that wasn''t there Nora pulls a new folder from box two: Mendez, Carol, 24, missing 14 Dec 1966, Stardust employee lot.It was not in the box last night. She inventoried the box last night.She takes the flyer out of her badge wallet and lays it next to the folder. Same face.","date":"1996-11-28","year":1996,"precision":"day","dateLabel":"Las Vegas · 28 Nov 1996 · ch 6","order":6,"type":"event","status":"proposal","location":"Las Vegas","characters":"Nora Reyes, Carol Mendez","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-7","title":"Jo gets two files and a phone","summary":"Jo gets two files and a phone Lake Mead unit. Two cold cases, same address, thirty years apart. Supervisor: \"Probably nothing. Clear it.\"Evidence bag: black rotary phone. No cord.She plays tape one on a borrowed deck. Ruth Hadley. Jo has heard that voice on a VHS at Christmas. It''s her great-grandmother.","date":"2026-03-09","year":2026,"precision":"day","dateLabel":"Las Vegas · 9 Mar 2026 · ch 7","order":7,"type":"event","status":"proposal","location":"Las Vegas","characters":"Jo Hadley, Ruth Hadley","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-8","title":"Night nine — \"Don''t go looking\"","summary":"Night nine — \"Don''t go looking\" Hal has been to Boulder Highway. Met Gabe. Met a man who went to the lake and came back and won''t say what he saw.The woman: \"Her son is already gone. Don''t go looking. Please.\"Hal: \"You keep saying please like you know me.\" — \"I know what you wrote on the back of your sister''s note.\"","date":"1966-11-12","year":1966,"precision":"day","dateLabel":"Las Vegas · 12 Nov 1966 · ch 8","order":8,"type":"event","status":"proposal","location":"Las Vegas","characters":"Hal Wesley, Nora Reyes","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-9","title":"The phone rings","summary":"The phone rings Jo, alone in the evidence room, 1:50 AM. The bagged phone rings.She picks up. A woman: \"Is this the station?\"Jo: \"…Yeah. This is the station.\"","date":"2026-03-11","year":2026,"precision":"day","dateLabel":"Las Vegas · 11 Mar 2026 · ch 9","order":9,"type":"event","status":"proposal","location":"Las Vegas","characters":"Jo Hadley, Nora Reyes","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-10","title":"\"Where are you calling from?\"","summary":"\"Where are you calling from?\" Nora dials the on-air number for the ninth night. Hal: \"Where are you calling from?\" — \"Las Vegas.\" — \"What year?\"She tells him. He believes her faster than she expected. \"You''ve been reading my pads.\" — \"Every one.\"Somewhere else on the line, faintly, a third breath. Neither of them mentions it.","date":"1996-12-03","year":1996,"precision":"day","dateLabel":"Las Vegas · 3 Dec 1996 · ch 10","order":10,"type":"event","status":"proposal","location":"Las Vegas","characters":"Hal Wesley, Nora Reyes","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."},{"id":"lh-night-11","title":"Thanksgiving week","summary":"Thanksgiving week Howard Hughes is carried into the Desert Inn on a stretcher. Every reporter in town is at the Desert Inn.Hal signs off early. Writes two words under his own name on the pad: the lake.Leaves the pad on the desk. Takes the coffee.","date":"1966-11-23","year":1966,"precision":"day","dateLabel":"Las Vegas · 23 Nov 1966 · the last night","order":11,"type":"event","status":"proposal","location":"Las Vegas","characters":"Hal Wesley","outcome":"Proposed source event; continuity and causal details need approval.","notes":"Imported from Claude story bible v1. No chapter text exists."}],"links":[{"id":"lh-link-1","from":"lh-night-3","to":"lh-night-6","kind":"echo","crossTime":true,"label":"Warnings and changing evidence"},{"id":"lh-link-2","from":"lh-night-2","to":"lh-night-11","kind":"requires","label":"Ruth’s call motivates the lake decision"},{"id":"lh-link-3","from":"lh-night-4","to":"lh-night-10","kind":"requires","label":"Files lead to recognition across time"}],"objects":[{"id":"lh-phone","title":"Black rotary phone","description":"How the phone works · the triangle Nora (1996) → Hal (1966). She dials the old on-air number out of habit — a cop tries every number in a file. He picks up live. Night one she thinks it''s a prank. Night three she knows. Jo (2026) ← Nora (1996). Jo''s evidence-bag phone rings, plugged into nothing. \"Is this the station?\" It''s Nora, dialing the same handset thirty years earlier. Jo says yes because she doesn''t know what else to say. Hal hears Nora — and some nights Jo. Two women. Hal and the reader hear one. Jo knows things Nora can''t — she''s read Nora''s notes on Hal. Nobody hears everyone. Each woman thinks she is the only future. The rule. Nobody knows the future. They know the files. Change a life → change what''s left → the box changes. Nora is reading a book that rewrites itself every time she speaks. \"You''ve read my pads.\" — \"Every one.\" — \"They''re in my car.\" — \"They''re in a box.\"","owner":"KDUS studio / evidence bag","history":"The source proposes one handset across three eras; custody and routing await decisions."},{"id":"lh-pads","title":"Fifty legal pads","description":"Hal’s caller names and two words beneath each name.","owner":"Hal, then the archive boxes","history":"Preserved by Sam; donated by Dot in 1994."}],"decisions":[],"blender":{"drafts":[],"adoptedId":null},"editorialReviews":[{"id":"lh-review-v1","title":"Story bible v1 · proposal critique","en":"Proposal review only. No story changes approved.\n\n1. Chronology: Carol takes the Stardust job in November 1966, meets Tony, and becomes pregnant by spring, yet Nora is born in 1966 and is 30 in 1996. Choose either an earlier relationship/job date or a later birth and age. Preserve the names. Nora’s 18/19 December last-seen dates also need one agreed sequence.\n\n2. Opening and reveal order: rules promise three ordinary-caller chapters, but chapter 1 contains a supernatural warning and chapter 3 introduces the woman. Jo is called the entry point but first appears in chapter 7. Decide between a brief Jo opening and the current Hal opening. A fair two-women reveal needs seeded differences in knowledge, not an artificial ban on voice description.\n\n3. Mechanics and responsibility: define call routing, connection windows, who remembers superseded files, and whether a changed file is evidence of causation. Ray dying after Lenny changes route does not yet prove one life must replace another. Explain Danny’s danger and the human choices behind it; ''no villain'' does not remove responsibility.\n\nEnding recommendation: B, The quiet one. Its silence fits the adult voice and gives Hal’s choice emotional finality, provided we first resolve Nora’s fate and establish why Jo can let the cases rest. A introduces a new unexplained duplicate laugh. C needs a rule explaining how Jo remains present after her ancestry changes. No ending selected by Benji.\n\nCarol to Nora: keep provisionally. It gives Nora a personal stake and makes Hal’s refusal consequential, but fix the birth chronology and distinguish it from Jo’s parallel family dependency.\n\nAdditional checks: midnight to 4 is four hours despite the show title; explain the title. Identify Gabe, the man crossed out twice, and the brown-coat employer without adding unapproved biographies. Reconcile the deserted 1996 studio with the station ending in 1979 and preserved equipment. Verify station identity/frequency, historical anchors and police procedure before drafting. Avoid treating readership claims as established facts.\n\nNext: approve a chronology repair, choose the opening, settle the phone and memory rules, then decide an ending. Draft only after Benji explicitly authorizes chapters.","ar":"","fingerprint":"[]","sources":[],"createdAt":"2026-10-31","writer":"GPT","scope":"story bible proposal"}],"storyBible":{"version":1,"author":"Claude","status":"proposal","source":"/sources/the-last-hour-bible.html","sections":[{"id":"brief","title":"Brief","html":"\n  <h2>Brief</h2>\n  <p class=\"lead\">Every night at midnight, Hal Wesley opens the phone lines and lets Las Vegas talk. Cab drivers, cocktail waitresses, a retired pit boss who can''t stand being home. He plays their songs. He writes two words under every name.</p>\n  <ol>\n    <li>Then a woman calls. She doesn''t want a song. She says one thing about the caller before her — and that caller''s life changes.</li>\n    <li>She calls every night. She knows what''s in his shirt pocket. She knows about the storage unit in Reno. She has read every legal pad he ever filled — pads that are still in his trunk.</li>\n    <li>She is Detective Nora Reyes, 1996, sitting in the dead KDUS building three weeks before it''s demolished, with his boxes open and the studio phone in her hand.</li>\n    <li>And in 2026, Detective Jo Hadley has a rotary phone in an evidence bag, two cold files from the same address — a host who vanished in ''66, a detective who vanished in ''96 — and a phone that rings when it isn''t plugged into anything.</li>\n    <li>Nobody on the line knows the future. They know the <em>files</em>. And every warning rewrites the files in front of them.</li>\n  </ol>\n","text":"Brief Every night at midnight, Hal Wesley opens the phone lines and lets Las Vegas talk. Cab drivers, cocktail waitresses, a retired pit boss who can''t stand being home. He plays their songs. He writes two words under every name. Then a woman calls. She doesn''t want a song. She says one thing about the caller before her — and that caller''s life changes. She calls every night. She knows what''s in his shirt pocket. She knows about the storage unit in Reno. She has read every legal pad he ever filled — pads that are still in his trunk. She is Detective Nora Reyes, 1996, sitting in the dead KDUS building three weeks before it''s demolished, with his boxes open and the studio phone in her hand. And in 2026, Detective Jo Hadley has a rotary phone in an evidence bag, two cold files from the same address — a host who vanished in ''66, a detective who vanished in ''96 — and a phone that rings when it isn''t plugged into anything. Nobody on the line knows the future. They know the files. And every warning rewrites the files in front of them."},{"id":"times","title":"Three Times · one phone line","html":"\n  <h2>Three Times · one phone line</h2>\n  <div class=\"times\">\n    <div class=\"time t66\"><b>1966</b><div class=\"who\">Hal · the host</div>\n      <ol><li>Las Vegas, autumn. KDUS 1340 AM, Industrial Road. \"The Last Hour,\" midnight–4.</li><li>Howard Hughes is about to arrive on a stretcher and buy the town. Nobody is watching a small AM station.</li><li>Hal vanishes Thanksgiving week.</li></ol></div>\n    <div class=\"time t96\"><b>1996</b><div class=\"who\">Nora · the detective</div>\n      <ol><li>Las Vegas is imploding the sixties — the Sands comes down 26 Nov. The KDUS building is next.</li><li>Nora has three weeks, four boxes, fifty legal pads, Sam''s call sheets, reel-to-reel tapes — and the studio phone, still wired.</li><li>She dials. He answers. On the air.</li></ol></div>\n    <div class=\"time t26\"><b>2026</b><div class=\"who\">Jo · the one who''s left</div>\n      <ol><li>Cold-case unit reopened after bodies surfaced in barrels at Lake Mead (2022).</li><li>Two files, one address, thirty years apart. Building''s a parking structure now. The boxes survived.</li><li>In one box: a black rotary phone. It rings.</li></ol></div>\n  </div>\n","text":"Three Times · one phone line 1966Hal · the host Las Vegas, autumn. KDUS 1340 AM, Industrial Road. \"The Last Hour,\" midnight–4.Howard Hughes is about to arrive on a stretcher and buy the town. Nobody is watching a small AM station.Hal vanishes Thanksgiving week. 1996Nora · the detective Las Vegas is imploding the sixties — the Sands comes down 26 Nov. The KDUS building is next.Nora has three weeks, four boxes, fifty legal pads, Sam''s call sheets, reel-to-reel tapes — and the studio phone, still wired.She dials. He answers. On the air. 2026Jo · the one who''s left Cold-case unit reopened after bodies surfaced in barrels at Lake Mead (2022).Two files, one address, thirty years apart. Building''s a parking structure now. The boxes survived.In one box: a black rotary phone. It rings."},{"id":"phone","title":"How the phone works · the triangle","html":"\n  <h2>How the phone works · the triangle</h2>\n  <ol>\n    <li><b>Nora (1996) → Hal (1966).</b> She dials the old on-air number out of habit — a cop tries every number in a file. He picks up live. Night one she thinks it''s a prank. Night three she knows.</li>\n    <li><b>Jo (2026) ← Nora (1996).</b> Jo''s evidence-bag phone rings, plugged into nothing. \"Is this the station?\" It''s Nora, dialing the same handset thirty years earlier. Jo says yes because she doesn''t know what else to say.</li>\n    <li><b>Hal hears Nora — and some nights Jo.</b> Two women. Hal and the reader hear one. Jo knows things Nora can''t — she''s read Nora''s notes <em>on</em> Hal.</li>\n    <li><b>Nobody hears everyone.</b> Each woman thinks she is the only future.</li>\n    <li><b>The rule.</b> Nobody knows the future. They know the files. Change a life → change what''s left → the box changes. Nora is reading a book that rewrites itself every time she speaks.</li>\n  </ol>\n  <div class=\"q\">\"You''ve read my pads.\" — \"Every one.\" — \"They''re in my car.\" — \"They''re in a box.\"</div>\n","text":"How the phone works · the triangle Nora (1996) → Hal (1966). She dials the old on-air number out of habit — a cop tries every number in a file. He picks up live. Night one she thinks it''s a prank. Night three she knows. Jo (2026) ← Nora (1996). Jo''s evidence-bag phone rings, plugged into nothing. \"Is this the station?\" It''s Nora, dialing the same handset thirty years earlier. Jo says yes because she doesn''t know what else to say. Hal hears Nora — and some nights Jo. Two women. Hal and the reader hear one. Jo knows things Nora can''t — she''s read Nora''s notes on Hal. Nobody hears everyone. Each woman thinks she is the only future. The rule. Nobody knows the future. They know the files. Change a life → change what''s left → the box changes. Nora is reading a book that rewrites itself every time she speaks. \"You''ve read my pads.\" — \"Every one.\" — \"They''re in my car.\" — \"They''re in a box.\""},{"id":"cast","title":"Characters","html":"\n  <h2>Characters</h2>\n  <div class=\"grid\">\n\n    <div class=\"card\"><span class=\"yr y66\">1966</span><div class=\"role\">the host</div><h3>Hal Wesley, 34</h3>\n      <ul><li>Host, \"The Last Hour,\" KDUS 1340 AM, midnight–4, six nights.</li><li>From Bakersfield. Came in ''61 after a divorce he never mentions.</li><li>Black coffee in a paper cup until a skin forms. Yellow legal pad: name, two words.</li><li>Helps strangers at 2 AM; lets his sister''s storage unit in Reno sit a year.</li><li>Keeps every pad. Fifty of them, in the trunk of a ''59 Impala.</li><li>Sign-on: <em>\"If you''re still working, God bless you. If you''re done and can''t shut it off — stay a while.\"</em></li><li><b>Fate:</b> vanishes at Lake Mead, 23 Nov 1966. By choice. (Reader learns \"by choice\" last.)</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y66\">1966</span><div class=\"role\">producer · screener</div><h3>Sam Pruitt, 41</h3>\n      <ul><li>Ex-Army radio operator, Korea. Knows what a lying voice sounds like.</li><li>Two fingers through the glass. Crosses out callers he doesn''t like — twice if he really doesn''t.</li><li>Wants the show on the clock. Hal always runs long.</li><li><b>Secret:</b> he hears what the woman is before Hal does. Lets her through anyway. Last sheet in the box: <em>\"It''s her again. Let her through.\"</em></li><li>Dies 1994, Henderson. His widow Dot gives the county four boxes from the garage.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y96\">1996</span><div class=\"role\">detective · the voice</div><h3>Nora Reyes, 30</h3>\n      <ul><li>LVMPD cold case, two years in. Patrol before that.</li><li>Officially: close the Industrial Road file before demolition. Really: find her mother.</li><li>Dials every number in every file. Can''t leave a phone unrung.</li><li>Objects: county flashlight, the black studio phone, her mother''s missing-person flyer folded in her badge wallet.</li><li>Voice: clipped, cop-flat — until night three, when it isn''t.</li><li><b>Secret:</b> daughter of Carol Mendez (missing Dec 1966) and Tony Reyes, Stardust dealer. Born 1966. She is in the files she''s reading.</li><li><b>Fate:</b> last seen entering 2201 Industrial Road, 18 Dec 1996. Demolished 19 Dec.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y26\">2026</span><div class=\"role\">detective · the reader''s eyes</div><h3>Jo Hadley, 26</h3>\n      <ul><li>LVMPD cold case, Lake Mead unit. Youngest in the room. Records everything as voice memos because she doesn''t trust her own handwriting.</li><li>Granddaughter of Danny Hadley — the electrician who went to the lake in 1966 and <em>came back</em>. Her great-grandmother Ruth''s voice is the first tape she plays.</li><li>Believes paper. Has to unlearn it.</li><li>Objects: rotary phone in an evidence bag; a charger she keeps reaching for on a phone with no port.</li><li>Voice: dry, tired, says \"okay\" a lot. The only person in the book who sounds like now.</li><li><b>Secret:</b> she exists because Hal went to the lake. Warn him off, unmake her grandfather. She figures it out before she tells him. Tells him anyway.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y66\">1966</span><div class=\"role\">caller · the mother</div><h3>Ruth Hadley, 58</h3>\n      <ul><li>Cocktail waitress, the Fremont, graveyard.</li><li>Calls 2 Nov 1966, 1:40 AM, from the payphone at the end of the bar. Slot machines behind her. A roll of dimes.</li><li>\"Twenty-seven days.\" Two calls home from her son: <em>I''m here.</em> Then: <em>the site changed, we''re closer to the water now.</em> She didn''t catch the name. She was asking if he''d eaten.</li><li>\"I don''t want anyone in trouble. I want him to call me.\"</li><li><b>Fate:</b> Danny comes home in December. She never knows why. Listens to the show for years after it''s gone, to static.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y66\">1966</span><div class=\"role\">the missing son</div><h3>Danny Hadley, 26</h3>\n      <ul><li>Electrician. Navy, two years, Subic Bay.</li><li>Hired off Boulder Highway: \"resort maintenance at the lake.\" Cash. No paperwork.</li><li><b>Fate:</b> comes back. Never talks about it. Raises a family in Henderson. Dies 2019. His granddaughter is Jo.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y66\">1966</span><div class=\"role\">regular caller</div><h3>Lenny Kostas, 44</h3>\n      <ul><li>Cab driver, Yellow-Checker, nights. Wife Dolores sews with the radio on.</li><li>Anniversary call: \"Tell her I remembered.\" — \"Tell her yourself, she''s listening.\" — \"Honey. One o''clock. Don''t wait up.\"</li><li><b>Fate:</b> the woman''s first warning sends him down Fremont instead of Boulder Highway. He lives. Never knows why he changed routes. Calls every anniversary until the station goes dark in ''79.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y66\">1966</span><div class=\"role\">regular caller · Nora''s mother</div><h3>Carol Mendez, 24</h3>\n      <ul><li>Cocktail waitress, the Mint. Offered a dealer job at the Stardust — graveyard, better money. Father says no \"because I said.\"</li><li>Hal catches himself siding with the father. Corrects it on air.</li><li><b>Fate:</b> takes the job. Meets Tony Reyes. Pregnant by spring. Vanishes 14 Dec 1966, Stardust employee lot.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y66\">1966</span><div class=\"role\">regular caller · the untouched life</div><h3>Earl Vance, 63</h3>\n      <ul><li>Retired pit boss, Golden Nugget, one month out. Wife can''t stand him home.</li><li>\"What are you in a hurry for at 6 AM?\" — \"That''s the thing I can''t answer.\"</li><li>Dedicates \"Unforgettable.\"</li><li><b>Fate:</b> nothing happens to him. The line never touches him. The reader needs one of those.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y66\">1966</span><div class=\"role\">the front</div><h3>Sal Kessler, 50</h3>\n      <ul><li>Runs the day-labor office on Boulder Highway. Cash jobs. Men nobody files a report for.</li><li>Takes money and instructions from a man in a brown coat who leaves no number.</li><li>Doesn''t ask where the men go. That''s the crime.</li></ul></div>\n\n    <div class=\"card\"><span class=\"yr one\">1966 · 2026</span><div class=\"role\">the cop who closed it</div><h3>Deputy Wade Brandt, 28 → 88</h3>\n      <ul><li>1966: took Ruth''s report. Closed it \"voluntary departure\" in nine days.</li><li>2026: Boulder City, oxygen tank, sharp. Tells Jo the one thing nobody wrote down: <em>\"There was a woman calling that station every night. We traced it. The number didn''t exist.\"</em></li></ul></div>\n\n    <div class=\"card\"><span class=\"yr y96\">1994</span><div class=\"role\">the widow</div><h3>Dot Pruitt</h3>\n      <ul><li>Gives the county four boxes from Sam''s garage. \"He said somebody would come for them. He didn''t say when.\"</li></ul></div>\n\n  </div>\n","text":"Characters 1966the hostHal Wesley, 34 Host, \"The Last Hour,\" KDUS 1340 AM, midnight–4, six nights.From Bakersfield. Came in ''61 after a divorce he never mentions.Black coffee in a paper cup until a skin forms. Yellow legal pad: name, two words.Helps strangers at 2 AM; lets his sister''s storage unit in Reno sit a year.Keeps every pad. Fifty of them, in the trunk of a ''59 Impala.Sign-on: \"If you''re still working, God bless you. If you''re done and can''t shut it off — stay a while.\"Fate: vanishes at Lake Mead, 23 Nov 1966. By choice. (Reader learns \"by choice\" last.) 1966producer · screenerSam Pruitt, 41 Ex-Army radio operator, Korea. Knows what a lying voice sounds like.Two fingers through the glass. Crosses out callers he doesn''t like — twice if he really doesn''t.Wants the show on the clock. Hal always runs long.Secret: he hears what the woman is before Hal does. Lets her through anyway. Last sheet in the box: \"It''s her again. Let her through.\"Dies 1994, Henderson. His widow Dot gives the county four boxes from the garage. 1996detective · the voiceNora Reyes, 30 LVMPD cold case, two years in. Patrol before that.Officially: close the Industrial Road file before demolition. Really: find her mother.Dials every number in every file. Can''t leave a phone unrung.Objects: county flashlight, the black studio phone, her mother''s missing-person flyer folded in her badge wallet.Voice: clipped, cop-flat — until night three, when it isn''t.Secret: daughter of Carol Mendez (missing Dec 1966) and Tony Reyes, Stardust dealer. Born 1966. She is in the files she''s reading.Fate: last seen entering 2201 Industrial Road, 18 Dec 1996. Demolished 19 Dec. 2026detective · the reader''s eyesJo Hadley, 26 LVMPD cold case, Lake Mead unit. Youngest in the room. Records everything as voice memos because she doesn''t trust her own handwriting.Granddaughter of Danny Hadley — the electrician who went to the lake in 1966 and came back. Her great-grandmother Ruth''s voice is the first tape she plays.Believes paper. Has to unlearn it.Objects: rotary phone in an evidence bag; a charger she keeps reaching for on a phone with no port.Voice: dry, tired, says \"okay\" a lot. The only person in the book who sounds like now.Secret: she exists because Hal went to the lake. Warn him off, unmake her grandfather. She figures it out before she tells him. Tells him anyway. 1966caller · the motherRuth Hadley, 58 Cocktail waitress, the Fremont, graveyard.Calls 2 Nov 1966, 1:40 AM, from the payphone at the end of the bar. Slot machines behind her. A roll of dimes.\"Twenty-seven days.\" Two calls home from her son: I''m here. Then: the site changed, we''re closer to the water now. She didn''t catch the name. She was asking if he''d eaten.\"I don''t want anyone in trouble. I want him to call me.\"Fate: Danny comes home in December. She never knows why. Listens to the show for years after it''s gone, to static. 1966the missing sonDanny Hadley, 26 Electrician. Navy, two years, Subic Bay.Hired off Boulder Highway: \"resort maintenance at the lake.\" Cash. No paperwork.Fate: comes back. Never talks about it. Raises a family in Henderson. Dies 2019. His granddaughter is Jo. 1966regular callerLenny Kostas, 44 Cab driver, Yellow-Checker, nights. Wife Dolores sews with the radio on.Anniversary call: \"Tell her I remembered.\" — \"Tell her yourself, she''s listening.\" — \"Honey. One o''clock. Don''t wait up.\"Fate: the woman''s first warning sends him down Fremont instead of Boulder Highway. He lives. Never knows why he changed routes. Calls every anniversary until the station goes dark in ''79. 1966regular caller · Nora''s motherCarol Mendez, 24 Cocktail waitress, the Mint. Offered a dealer job at the Stardust — graveyard, better money. Father says no \"because I said.\"Hal catches himself siding with the father. Corrects it on air.Fate: takes the job. Meets Tony Reyes. Pregnant by spring. Vanishes 14 Dec 1966, Stardust employee lot. 1966regular caller · the untouched lifeEarl Vance, 63 Retired pit boss, Golden Nugget, one month out. Wife can''t stand him home.\"What are you in a hurry for at 6 AM?\" — \"That''s the thing I can''t answer.\"Dedicates \"Unforgettable.\"Fate: nothing happens to him. The line never touches him. The reader needs one of those. 1966the frontSal Kessler, 50 Runs the day-labor office on Boulder Highway. Cash jobs. Men nobody files a report for.Takes money and instructions from a man in a brown coat who leaves no number.Doesn''t ask where the men go. That''s the crime. 1966 · 2026the cop who closed itDeputy Wade Brandt, 28 → 88 1966: took Ruth''s report. Closed it \"voluntary departure\" in nine days.2026: Boulder City, oxygen tank, sharp. Tells Jo the one thing nobody wrote down: \"There was a woman calling that station every night. We traced it. The number didn''t exist.\" 1994the widowDot Pruitt Gives the county four boxes from Sam''s garage. \"He said somebody would come for them. He didn''t say when.\""},{"id":"callers","title":"The callers · why we love them first","html":"\n  <h2>The callers · why we love them first</h2>\n  <ol>\n    <li>Chapters 1–3 are <b>only</b> normal calls. No woman yet. The reader has to want Lenny to get home, want Carol to take the job, want Earl to figure out his mornings.</li>\n    <li>Every regular gets a <span class=\"pill\">song</span> a <span class=\"pill\">problem</span> and a <span class=\"pill\">line Hal gives back</span>. That''s the whole formula. Delilah, 1966.</li>\n    <li>By chapter 4 the reader knows the callers'' voices well enough that when the woman comments on one of them, it lands like someone talking about your friend.</li>\n    <li>The regulars keep calling after the woman appears. Their lives are the scoreboard: who''s still calling, who stopped.</li>\n  </ol>\n","text":"The callers · why we love them first Chapters 1–3 are only normal calls. No woman yet. The reader has to want Lenny to get home, want Carol to take the job, want Earl to figure out his mornings. Every regular gets a song a problem and a line Hal gives back. That''s the whole formula. Delilah, 1966. By chapter 4 the reader knows the callers'' voices well enough that when the woman comments on one of them, it lands like someone talking about your friend. The regulars keep calling after the woman appears. Their lives are the scoreboard: who''s still calling, who stopped."},{"id":"nights","title":"Nights & events · the spine","html":"\n  <h2>Nights &amp; events · the spine</h2>\n\n  <div class=\"night\"><div class=\"d\">Las Vegas · 28 Oct 1966 · ch 1</div><h4>Earl, Carol, Lenny, the recipe lady — and a man crossed out twice</h4>\n    <ol><li>Four warm calls. The formula lands.</li><li>Fifth caller won''t give his name, asked for Hal by a middle name he never uses on air. One sentence: <em>\"Don''t go to the lake, Hal.\"</em> Dial tone. Hal laughs. Sam doesn''t.</li><li>Close: note from Sam — <em>your sister called, Reno, storage unit</em>. Hal writes a time on the back, crosses it out. <em>Ask her first.</em></li></ol></div>\n\n  <div class=\"night\"><div class=\"d\">Las Vegas · 2 Nov 1966 · ch 2</div><h4>Ruth Hadley — \"Twenty-seven days\"</h4>\n    <ol><li>Office name and address off-air. \"We don''t pull people out of their homes on an accusation we know nothing about.\"</li><li>A later caller recognizes the Boulder Highway office: \"the destination was always going to change.\"</li><li>Hal doesn''t go home after.</li></ol></div>\n\n  <div class=\"night\"><div class=\"d\">Las Vegas · 4 Nov 1966 · ch 3</div><h4>The woman — night one</h4>\n    <ol><li>Lenny hangs up. New caller, a woman. No song. \"Tell him not to take Boulder Highway tonight.\"</li><li>Hal relays it as a joke. Lenny takes Fremont.</li><li>1:10 AM: a cab is hit head-on on Boulder Highway. Driver Ray Dunning, 38, dead. Lenny is alive. Somebody else isn''t. <b>Nobody''s hands are clean after night one.</b></li></ol></div>\n\n  <div class=\"night c96\"><div class=\"d\">Las Vegas · 27 Nov 1996 · ch 4</div><h4>Nora opens the boxes</h4>\n    <ol><li>The Sands came down last night; the whole town smells like concrete dust. Demolition order for 2201 Industrial Road: 19 Dec.</li><li>Four boxes. Fifty legal pads. Reel-to-reel. Sam''s call sheets with crossings-out.</li><li>She plays the first tape. Ruth Hadley''s voice. Slot machines.</li><li>The studio phone is still on the desk. She lifts it. There''s a tone.</li></ol></div>\n\n  <div class=\"night\"><div class=\"d\">Las Vegas · 7 Nov 1966 · ch 5</div><h4>Night four — Carol</h4>\n    <ol><li>Carol calls: she''s taking the Stardust job Monday.</li><li>The woman, after: \"Carol shouldn''t take that job.\" Hal doesn''t relay it. Felt like meddling.</li><li>Sam, through the glass, writes a word on the sheet and underlines it.</li></ol></div>\n\n  <div class=\"night c96\"><div class=\"d\">Las Vegas · 28 Nov 1996 · ch 6</div><h4>The file that wasn''t there</h4>\n    <ol><li>Nora pulls a new folder from box two: <em>Mendez, Carol, 24, missing 14 Dec 1966, Stardust employee lot.</em></li><li>It was not in the box last night. She inventoried the box last night.</li><li>She takes the flyer out of her badge wallet and lays it next to the folder. Same face.</li></ol></div>\n\n  <div class=\"night c26\"><div class=\"d\">Las Vegas · 9 Mar 2026 · ch 7</div><h4>Jo gets two files and a phone</h4>\n    <ol><li>Lake Mead unit. Two cold cases, same address, thirty years apart. Supervisor: \"Probably nothing. Clear it.\"</li><li>Evidence bag: black rotary phone. No cord.</li><li>She plays tape one on a borrowed deck. Ruth Hadley. Jo has heard that voice on a VHS at Christmas. It''s her great-grandmother.</li></ol></div>\n\n  <div class=\"night\"><div class=\"d\">Las Vegas · 12 Nov 1966 · ch 8</div><h4>Night nine — \"Don''t go looking\"</h4>\n    <ol><li>Hal has been to Boulder Highway. Met Gabe. Met a man who went to the lake and came back and won''t say what he saw.</li><li>The woman: \"Her son is already gone. Don''t go looking. Please.\"</li><li>Hal: \"You keep saying please like you know me.\" — \"I know what you wrote on the back of your sister''s note.\"</li></ol></div>\n\n  <div class=\"night c26\"><div class=\"d\">Las Vegas · 11 Mar 2026 · ch 9</div><h4>The phone rings</h4>\n    <ol><li>Jo, alone in the evidence room, 1:50 AM. The bagged phone rings.</li><li>She picks up. A woman: \"Is this the station?\"</li><li>Jo: \"…Yeah. This is the station.\"</li></ol></div>\n\n  <div class=\"night c96\"><div class=\"d\">Las Vegas · 3 Dec 1996 · ch 10</div><h4>\"Where are you calling from?\"</h4>\n    <ol><li>Nora dials the on-air number for the ninth night. Hal: \"Where are you calling from?\" — \"Las Vegas.\" — \"What year?\"</li><li>She tells him. He believes her faster than she expected. \"You''ve been reading my pads.\" — \"Every one.\"</li><li>Somewhere else on the line, faintly, a third breath. Neither of them mentions it.</li></ol></div>\n\n  <div class=\"night\"><div class=\"d\">Las Vegas · 23 Nov 1966 · the last night</div><h4>Thanksgiving week</h4>\n    <ol><li>Howard Hughes is carried into the Desert Inn on a stretcher. Every reporter in town is at the Desert Inn.</li><li>Hal signs off early. Writes two words under his own name on the pad: <em>the lake.</em></li><li>Leaves the pad on the desk. Takes the coffee.</li></ol></div>\n","text":"Nights & events · the spine Las Vegas · 28 Oct 1966 · ch 1Earl, Carol, Lenny, the recipe lady — and a man crossed out twice Four warm calls. The formula lands.Fifth caller won''t give his name, asked for Hal by a middle name he never uses on air. One sentence: \"Don''t go to the lake, Hal.\" Dial tone. Hal laughs. Sam doesn''t.Close: note from Sam — your sister called, Reno, storage unit. Hal writes a time on the back, crosses it out. Ask her first. Las Vegas · 2 Nov 1966 · ch 2Ruth Hadley — \"Twenty-seven days\" Office name and address off-air. \"We don''t pull people out of their homes on an accusation we know nothing about.\"A later caller recognizes the Boulder Highway office: \"the destination was always going to change.\"Hal doesn''t go home after. Las Vegas · 4 Nov 1966 · ch 3The woman — night one Lenny hangs up. New caller, a woman. No song. \"Tell him not to take Boulder Highway tonight.\"Hal relays it as a joke. Lenny takes Fremont.1:10 AM: a cab is hit head-on on Boulder Highway. Driver Ray Dunning, 38, dead. Lenny is alive. Somebody else isn''t. Nobody''s hands are clean after night one. Las Vegas · 27 Nov 1996 · ch 4Nora opens the boxes The Sands came down last night; the whole town smells like concrete dust. Demolition order for 2201 Industrial Road: 19 Dec.Four boxes. Fifty legal pads. Reel-to-reel. Sam''s call sheets with crossings-out.She plays the first tape. Ruth Hadley''s voice. Slot machines.The studio phone is still on the desk. She lifts it. There''s a tone. Las Vegas · 7 Nov 1966 · ch 5Night four — Carol Carol calls: she''s taking the Stardust job Monday.The woman, after: \"Carol shouldn''t take that job.\" Hal doesn''t relay it. Felt like meddling.Sam, through the glass, writes a word on the sheet and underlines it. Las Vegas · 28 Nov 1996 · ch 6The file that wasn''t there Nora pulls a new folder from box two: Mendez, Carol, 24, missing 14 Dec 1966, Stardust employee lot.It was not in the box last night. She inventoried the box last night.She takes the flyer out of her badge wallet and lays it next to the folder. Same face. Las Vegas · 9 Mar 2026 · ch 7Jo gets two files and a phone Lake Mead unit. Two cold cases, same address, thirty years apart. Supervisor: \"Probably nothing. Clear it.\"Evidence bag: black rotary phone. No cord.She plays tape one on a borrowed deck. Ruth Hadley. Jo has heard that voice on a VHS at Christmas. It''s her great-grandmother. Las Vegas · 12 Nov 1966 · ch 8Night nine — \"Don''t go looking\" Hal has been to Boulder Highway. Met Gabe. Met a man who went to the lake and came back and won''t say what he saw.The woman: \"Her son is already gone. Don''t go looking. Please.\"Hal: \"You keep saying please like you know me.\" — \"I know what you wrote on the back of your sister''s note.\" Las Vegas · 11 Mar 2026 · ch 9The phone rings Jo, alone in the evidence room, 1:50 AM. The bagged phone rings.She picks up. A woman: \"Is this the station?\"Jo: \"…Yeah. This is the station.\" Las Vegas · 3 Dec 1996 · ch 10\"Where are you calling from?\" Nora dials the on-air number for the ninth night. Hal: \"Where are you calling from?\" — \"Las Vegas.\" — \"What year?\"She tells him. He believes her faster than she expected. \"You''ve been reading my pads.\" — \"Every one.\"Somewhere else on the line, faintly, a third breath. Neither of them mentions it. Las Vegas · 23 Nov 1966 · the last nightThanksgiving week Howard Hughes is carried into the Desert Inn on a stretcher. Every reporter in town is at the Desert Inn.Hal signs off early. Writes two words under his own name on the pad: the lake.Leaves the pad on the desk. Takes the coffee."},{"id":"twists","title":"Plot twists · in reading order","html":"\n  <h2>Plot twists · in reading order</h2>\n  <div class=\"twist\"><div class=\"n\">1</div><div><h4>The warning costs</h4><p>The woman''s first comment saves Lenny and kills Ray Dunning. She didn''t know. Hal didn''t know. The reader learns the line isn''t free.</p></div></div>\n  <div class=\"twist\"><div class=\"n\">2</div><div><h4>The files change</h4><p>Carol''s folder appears in Nora''s box overnight. Nora isn''t reading history. She''s reading consequences — of what she said last night.</p></div></div>\n  <div class=\"twist\"><div class=\"n\">3</div><div><h4>\"They''re in a box.\"</h4><p>Hal realizes the woman has read things nobody saw him write. He asks where his pads are. She tells him.</p></div></div>\n  <div class=\"twist\"><div class=\"n\">4</div><div><h4>Two women</h4><p>One night \"she\" contradicts herself. Nora has never heard of a Lake Mead barrel. The other voice has. Reader splits the voice in two for the first time.</p></div></div>\n  <div class=\"twist\"><div class=\"n\">5</div><div><h4>Hal dials forward</h4><p>Jo''s phone rings and it isn''t Nora. It''s Hal. He''s figured out the triangle before either woman and he''s calling the far end to ask the only question: <em>\"Did I go to the lake?\"</em></p></div></div>\n  <div class=\"twist\"><div class=\"n\">6</div><div><h4>Nora''s own file</h4><p>Box three, bottom: <em>Reyes, N., Det., 30, missing 19 Dec 1996, last seen entering 2201 Industrial Road.</em> She is sitting at 2201 Industrial Road. It is 18 Dec.</p></div></div>\n  <div class=\"twist\"><div class=\"n\">7</div><div><h4>The bloodline</h4><p>Nora asked Hal to stop Carol taking the Stardust job — to save her mother. Hal stayed quiet. Carol took the job, met Tony Reyes, had Nora. Nora exists because Hal ignored her.</p></div></div>\n  <div class=\"twist\"><div class=\"n\">8</div><div><h4>Jo tells the truth</h4><p>\"Yes. You went. Danny Hadley came home. His mother got him back. I''m his granddaughter.\" Hal chooses the trade. He vanishes while the whole city watches a billionaire on a stretcher.</p></div></div>\n  <div class=\"twist\"><div class=\"n\">9</div><div><h4>Sam knew</h4><p>Last call sheet in the box, Sam''s pencil: <em>\"It''s her again. Let her through.\"</em> The screener recognized what she was on night one and opened the door every night after.</p></div></div>\n","text":"Plot twists · in reading order 1The warning costsThe woman''s first comment saves Lenny and kills Ray Dunning. She didn''t know. Hal didn''t know. The reader learns the line isn''t free. 2The files changeCarol''s folder appears in Nora''s box overnight. Nora isn''t reading history. She''s reading consequences — of what she said last night. 3\"They''re in a box.\"Hal realizes the woman has read things nobody saw him write. He asks where his pads are. She tells him. 4Two womenOne night \"she\" contradicts herself. Nora has never heard of a Lake Mead barrel. The other voice has. Reader splits the voice in two for the first time. 5Hal dials forwardJo''s phone rings and it isn''t Nora. It''s Hal. He''s figured out the triangle before either woman and he''s calling the far end to ask the only question: \"Did I go to the lake?\" 6Nora''s own fileBox three, bottom: Reyes, N., Det., 30, missing 19 Dec 1996, last seen entering 2201 Industrial Road. She is sitting at 2201 Industrial Road. It is 18 Dec. 7The bloodlineNora asked Hal to stop Carol taking the Stardust job — to save her mother. Hal stayed quiet. Carol took the job, met Tony Reyes, had Nora. Nora exists because Hal ignored her. 8Jo tells the truth\"Yes. You went. Danny Hadley came home. His mother got him back. I''m his granddaughter.\" Hal chooses the trade. He vanishes while the whole city watches a billionaire on a stretcher. 9Sam knewLast call sheet in the box, Sam''s pencil: \"It''s her again. Let her through.\" The screener recognized what she was on night one and opened the door every night after."},{"id":"endings","title":"Endings · pick one","html":"\n  <h2>Endings · pick one</h2>\n  <div class=\"end\"><h4>A · The last call</h4><ol><li>Nora stays past the 18th for one more call. Dials. Hal answers. She tells him everything she knows — which is now everything.</li><li>Wrecking ball, 19 Dec. The file was right.</li><li>2026: Jo plugs the phone in one last time. It rings. A man: <em>\"If you''re still working, God bless you…\"</em> A woman laughs in the background. Jo knows the laugh. It''s hers.</li></ol></div>\n  <div class=\"end\"><h4>B · The quiet one</h4><ol><li>Jo closes both cases \"undetermined,\" takes the phone home, keeps it on the nightstand.</li><li>It never rings.</li><li>Last line: she sleeps better than she has in years — which is how she knows he''s done calling.</li></ol></div>\n  <div class=\"end\"><h4>C · The trade undone</h4><ol><li>Jo warns Hal off the lake. He stays. Danny Hadley never comes home. Ruth listens to static.</li><li>Jo''s phone goes dead mid-sentence. The evidence bag is empty. Her supervisor doesn''t remember assigning her the case.</li><li>She drives to Henderson. The house her grandfather built isn''t there.</li></ol></div>\n","text":"Endings · pick one A · The last callNora stays past the 18th for one more call. Dials. Hal answers. She tells him everything she knows — which is now everything.Wrecking ball, 19 Dec. The file was right.2026: Jo plugs the phone in one last time. It rings. A man: \"If you''re still working, God bless you…\" A woman laughs in the background. Jo knows the laugh. It''s hers. B · The quiet oneJo closes both cases \"undetermined,\" takes the phone home, keeps it on the nightstand.It never rings.Last line: she sleeps better than she has in years — which is how she knows he''s done calling. C · The trade undoneJo warns Hal off the lake. He stays. Danny Hadley never comes home. Ruth listens to static.Jo''s phone goes dead mid-sentence. The evidence bag is empty. Her supervisor doesn''t remember assigning her the case.She drives to Henderson. The house her grandfather built isn''t there."},{"id":"genz","title":"Why Gen Z reads it · and how the page stays readable","html":"\n  <h2>Why Gen Z reads it · and how the page stays readable</h2>\n  <ol>\n    <li><b>Jo is the way in.</b> 26, voice memos, \"okay,\" a charger reaching for a phone with no port. Every 2026 chapter opens with a voice-memo transcript — timestamped, lowercase, the way she actually talks. That''s the PATTERN group-chat trick, rebuilt for one person alone in an evidence room.</li>\n    <li><b>Analog is the horror.</b> No caller ID. No screenshots. No way to prove any of it. The three of them have to believe each other or hang up.</li>\n    <li><b>Every chapter is one night.</b> 12–18 minutes read aloud. Each one ends on a line, not a scene. Built for audio chapters on YouTube like PATTERN.</li>\n    <li><b>No villain.</b> A cop who closed a file to protect a mother. A host who traded himself for a stranger''s son. A screener who let the impossible call through. Everyone''s complicated. Nobody''s evil. Gen Z doesn''t trust villains anyway.</li>\n    <li><b>The love story is the warning.</b> Nobody kisses anybody. Nora and Hal talk for nine nights across thirty years and the most intimate thing in the book is a man saying \"they''re in my car\" and a woman saying \"they''re in a box.\"</li>\n    <li><b>Real and Googleable.</b> Hughes''s stretcher. The Sands implosion. The barrels. St. Thomas under the lake. A reader can check every anchor on their phone and find it''s true — which makes the one thing that isn''t feel true too.</li>\n    <li><b>The voice stays adult.</b> Short declaratives, no adverbs, dialogue does the work. Gen Z friendly is about the entry point and the pacing — not slang. PATTERN is the slang one; this is the quiet one.</li>\n  </ol>\n","text":"Why Gen Z reads it · and how the page stays readable Jo is the way in. 26, voice memos, \"okay,\" a charger reaching for a phone with no port. Every 2026 chapter opens with a voice-memo transcript — timestamped, lowercase, the way she actually talks. That''s the PATTERN group-chat trick, rebuilt for one person alone in an evidence room. Analog is the horror. No caller ID. No screenshots. No way to prove any of it. The three of them have to believe each other or hang up. Every chapter is one night. 12–18 minutes read aloud. Each one ends on a line, not a scene. Built for audio chapters on YouTube like PATTERN. No villain. A cop who closed a file to protect a mother. A host who traded himself for a stranger''s son. A screener who let the impossible call through. Everyone''s complicated. Nobody''s evil. Gen Z doesn''t trust villains anyway. The love story is the warning. Nobody kisses anybody. Nora and Hal talk for nine nights across thirty years and the most intimate thing in the book is a man saying \"they''re in my car\" and a woman saying \"they''re in a box.\" Real and Googleable. Hughes''s stretcher. The Sands implosion. The barrels. St. Thomas under the lake. A reader can check every anchor on their phone and find it''s true — which makes the one thing that isn''t feel true too. The voice stays adult. Short declaratives, no adverbs, dialogue does the work. Gen Z friendly is about the entry point and the pacing — not slang. PATTERN is the slang one; this is the quiet one."},{"id":"real","title":"Real events used as furniture","html":"\n  <h2>Real events used as furniture</h2>\n  <ol>\n    <li><b>11 Jun 1938</b> — Hugh Lord, last resident of St. Thomas, Nevada, rows away as Lake Mead reaches his house. The town goes under. (The lake is where the men are sent. The town is what''s down there.)</li>\n    <li><b>1960s</b> — Nevada Test Site underground shots 65 miles north; Vegas hotels sway. Callers mention the shaking.</li>\n    <li><b>Thanksgiving 1966</b> — Howard Hughes arrives by train, carried into the Desert Inn on a stretcher, starts buying the Strip. Hal vanishes the same week.</li>\n    <li><b>26 Nov 1996</b> — the Sands is imploded. Vegas is tearing down the sixties. Nora''s building is next.</li>\n    <li><b>May 2022</b> — human remains in a barrel surface at Hemenway Harbor as Lake Mead drops; more follow. Cold cases reopen. Jo gets hired.</li>\n    <li><b>2022–2026</b> — record lows; St. Thomas fully walkable. <span class=\"pill\">verify at research pass</span></li>\n  </ol>\n  <p style=\"color:var(--mute);font-size:14px\">Rule: real events are mentioned by callers, on a bar TV, in a headline. Never explained. Never the plot.</p>\n","text":"Real events used as furniture 11 Jun 1938 — Hugh Lord, last resident of St. Thomas, Nevada, rows away as Lake Mead reaches his house. The town goes under. (The lake is where the men are sent. The town is what''s down there.) 1960s — Nevada Test Site underground shots 65 miles north; Vegas hotels sway. Callers mention the shaking. Thanksgiving 1966 — Howard Hughes arrives by train, carried into the Desert Inn on a stretcher, starts buying the Strip. Hal vanishes the same week. 26 Nov 1996 — the Sands is imploded. Vegas is tearing down the sixties. Nora''s building is next. May 2022 — human remains in a barrel surface at Hemenway Harbor as Lake Mead drops; more follow. Cold cases reopen. Jo gets hired. 2022–2026 — record lows; St. Thomas fully walkable. verify at research pass Rule: real events are mentioned by callers, on a bar TV, in a headline. Never explained. Never the plot."},{"id":"rules","title":"Writing rules","html":"\n  <h2>Writing rules</h2>\n  <div class=\"rule\"><b>01</b><div>Every chapter opens with place + date. Three times, three dates, never blurred.</div></div>\n  <div class=\"rule\"><b>02</b><div>One object per time: paper cup with a skin (1966) · county flashlight (1996) · evidence bag (2026). Objects don''t cross timelines until a twist needs them to.</div></div>\n  <div class=\"rule\"><b>03</b><div>One light per time: studio red + fluorescent · a flashlight in a dead building · evidence-room white.</div></div>\n  <div class=\"rule\"><b>04</b><div>Chapters 1–3: callers only. The woman does not appear until the reader loves at least two of them.</div></div>\n  <div class=\"rule\"><b>05</b><div>The woman is never described by voice until twist 4 — only by her words. The reader has to be able to merge two women into one.</div></div>\n  <div class=\"rule\"><b>06</b><div>Nobody knows the future. They know files. If a character predicts something that isn''t in a file, that''s a mistake.</div></div>\n  <div class=\"rule\"><b>07</b><div>Short declaratives. No adverbs. Dialogue does the work. Kent Haruf, Denis Johnson — not a podcast.</div></div>\n  <div class=\"rule\"><b>08</b><div>Don''t invent a date for an unknown day. Leave it unknown.</div></div>\n  <div class=\"rule\"><b>09</b><div>Written chapters and proposed events are two different states. This page is 100% proposed.</div></div>\n","text":"Writing rules 01Every chapter opens with place + date. Three times, three dates, never blurred. 02One object per time: paper cup with a skin (1966) · county flashlight (1996) · evidence bag (2026). Objects don''t cross timelines until a twist needs them to. 03One light per time: studio red + fluorescent · a flashlight in a dead building · evidence-room white. 04Chapters 1–3: callers only. The woman does not appear until the reader loves at least two of them. 05The woman is never described by voice until twist 4 — only by her words. The reader has to be able to merge two women into one. 06Nobody knows the future. They know files. If a character predicts something that isn''t in a file, that''s a mistake. 07Short declaratives. No adverbs. Dialogue does the work. Kent Haruf, Denis Johnson — not a podcast. 08Don''t invent a date for an unknown day. Leave it unknown. 09Written chapters and proposed events are two different states. This page is 100% proposed."}]},"storyBrief":{"text":"Brief\nBrief Every night at midnight, Hal Wesley opens the phone lines and lets Las Vegas talk. Cab drivers, cocktail waitresses, a retired pit boss who can''t stand being home. He plays their songs. He writes two words under every name. Then a woman calls. She doesn''t want a song. She says one thing about the caller before her — and that caller''s life changes. She calls every night. She knows what''s in his shirt pocket. She knows about the storage unit in Reno. She has read every legal pad he ever filled — pads that are still in his trunk. She is Detective Nora Reyes, 1996, sitting in the dead KDUS building three weeks before it''s demolished, with his boxes open and the studio phone in her hand. And in 2026, Detective Jo Hadley has a rotary phone in an evidence bag, two cold files from the same address — a host who vanished in ''66, a detective who vanished in ''96 — and a phone that rings when it isn''t plugged into anything. Nobody on the line knows the future. They know the files. And every warning rewrites the files in front of them.\n\nThree Times · one phone line\nThree Times · one phone line 1966Hal · the host Las Vegas, autumn. KDUS 1340 AM, Industrial Road. \"The Last Hour,\" midnight–4.Howard Hughes is about to arrive on a stretcher and buy the town. Nobody is watching a small AM station.Hal vanishes Thanksgiving week. 1996Nora · the detective Las Vegas is imploding the sixties — the Sands comes down 26 Nov. The KDUS building is next.Nora has three weeks, four boxes, fifty legal pads, Sam''s call sheets, reel-to-reel tapes — and the studio phone, still wired.She dials. He answers. On the air. 2026Jo · the one who''s left Cold-case unit reopened after bodies surfaced in barrels at Lake Mead (2022).Two files, one address, thirty years apart. Building''s a parking structure now. The boxes survived.In one box: a black rotary phone. It rings.\n\nHow the phone works · the triangle\nHow the phone works · the triangle Nora (1996) → Hal (1966). She dials the old on-air number out of habit — a cop tries every number in a file. He picks up live. Night one she thinks it''s a prank. Night three she knows. Jo (2026) ← Nora (1996). Jo''s evidence-bag phone rings, plugged into nothing. \"Is this the station?\" It''s Nora, dialing the same handset thirty years earlier. Jo says yes because she doesn''t know what else to say. Hal hears Nora — and some nights Jo. Two women. Hal and the reader hear one. Jo knows things Nora can''t — she''s read Nora''s notes on Hal. Nobody hears everyone. Each woman thinks she is the only future. The rule. Nobody knows the future. They know the files. Change a life → change what''s left → the box changes. Nora is reading a book that rewrites itself every time she speaks. \"You''ve read my pads.\" — \"Every one.\" — \"They''re in my car.\" — \"They''re in a box.\"\n\nCharacters\nCharacters 1966the hostHal Wesley, 34 Host, \"The Last Hour,\" KDUS 1340 AM, midnight–4, six nights.From Bakersfield. Came in ''61 after a divorce he never mentions.Black coffee in a paper cup until a skin forms. Yellow legal pad: name, two words.Helps strangers at 2 AM; lets his sister''s storage unit in Reno sit a year.Keeps every pad. Fifty of them, in the trunk of a ''59 Impala.Sign-on: \"If you''re still working, God bless you. If you''re done and can''t shut it off — stay a while.\"Fate: vanishes at Lake Mead, 23 Nov 1966. By choice. (Reader learns \"by choice\" last.) 1966producer · screenerSam Pruitt, 41 Ex-Army radio operator, Korea. Knows what a lying voice sounds like.Two fingers through the glass. Crosses out callers he doesn''t like — twice if he really doesn''t.Wants the show on the clock. Hal always runs long.Secret: he hears what the woman is before Hal does. Lets her through anyway. Last sheet in the box: \"It''s her again. Let her through.\"Dies 1994, Henderson. His widow Dot gives the county four boxes from the garage. 1996detective · the voiceNora Reyes, 30 LVMPD cold case, two years in. Patrol before that.Officially: close the Industrial Road file before demolition. Really: find her mother.Dials every number in every file. Can''t leave a phone unrung.Objects: county flashlight, the black studio phone, her mother''s missing-person flyer folded in her badge wallet.Voice: clipped, cop-flat — until night three, when it isn''t.Secret: daughter of Carol Mendez (missing Dec 1966) and Tony Reyes, Stardust dealer. Born 1966. She is in the files she''s reading.Fate: last seen entering 2201 Industrial Road, 18 Dec 1996. Demolished 19 Dec. 2026detective · the reader''s eyesJo Hadley, 26 LVMPD cold case, Lake Mead unit. Youngest in the room. Records everything as voice memos because she doesn''t trust her own handwriting.Granddaughter of Danny Hadley — the electrician who went to the lake in 1966 and came back. Her great-grandmother Ruth''s voice is the first tape she plays.Believes paper. Has to unlearn it.Objects: rotary phone in an evidence bag; a charger she keeps reaching for on a phone with no port.Voice: dry, tired, says \"okay\" a lot. The only person in the book who sounds like now.Secret: she exists because Hal went to the lake. Warn him off, unmake her grandfather. She figures it out before she tells him. Tells him anyway. 1966caller · the motherRuth Hadley, 58 Cocktail waitress, the Fremont, graveyard.Calls 2 Nov 1966, 1:40 AM, from the payphone at the end of the bar. Slot machines behind her. A roll of dimes.\"Twenty-seven days.\" Two calls home from her son: I''m here. Then: the site changed, we''re closer to the water now. She didn''t catch the name. She was asking if he''d eaten.\"I don''t want anyone in trouble. I want him to call me.\"Fate: Danny comes home in December. She never knows why. Listens to the show for years after it''s gone, to static. 1966the missing sonDanny Hadley, 26 Electrician. Navy, two years, Subic Bay.Hired off Boulder Highway: \"resort maintenance at the lake.\" Cash. No paperwork.Fate: comes back. Never talks about it. Raises a family in Henderson. Dies 2019. His granddaughter is Jo. 1966regular callerLenny Kostas, 44 Cab driver, Yellow-Checker, nights. Wife Dolores sews with the radio on.Anniversary call: \"Tell her I remembered.\" — \"Tell her yourself, she''s listening.\" — \"Honey. One o''clock. Don''t wait up.\"Fate: the woman''s first warning sends him down Fremont instead of Boulder Highway. He lives. Never knows why he changed routes. Calls every anniversary until the station goes dark in ''79. 1966regular caller · Nora''s motherCarol Mendez, 24 Cocktail waitress, the Mint. Offered a dealer job at the Stardust — graveyard, better money. Father says no \"because I said.\"Hal catches himself siding with the father. Corrects it on air.Fate: takes the job. Meets Tony Reyes. Pregnant by spring. Vanishes 14 Dec 1966, Stardust employee lot. 1966regular caller · the untouched lifeEarl Vance, 63 Retired pit boss, Golden Nugget, one month out. Wife can''t stand him home.\"What are you in a hurry for at 6 AM?\" — \"That''s the thing I can''t answer.\"Dedicates \"Unforgettable.\"Fate: nothing happens to him. The line never touches him. The reader needs one of those. 1966the frontSal Kessler, 50 Runs the day-labor office on Boulder Highway. Cash jobs. Men nobody files a report for.Takes money and instructions from a man in a brown coat who leaves no number.Doesn''t ask where the men go. That''s the crime. 1966 · 2026the cop who closed itDeputy Wade Brandt, 28 → 88 1966: took Ruth''s report. Closed it \"voluntary departure\" in nine days.2026: Boulder City, oxygen tank, sharp. Tells Jo the one thing nobody wrote down: \"There was a woman calling that station every night. We traced it. The number didn''t exist.\" 1994the widowDot Pruitt Gives the county four boxes from Sam''s garage. \"He said somebody would come for them. He didn''t say when.\"\n\nThe callers · why we love them first\nThe callers · why we love them first Chapters 1–3 are only normal calls. No woman yet. The reader has to want Lenny to get home, want Carol to take the job, want Earl to figure out his mornings. Every regular gets a song a problem and a line Hal gives back. That''s the whole formula. Delilah, 1966. By chapter 4 the reader knows the callers'' voices well enough that when the woman comments on one of them, it lands like someone talking about your friend. The regulars keep calling after the woman appears. Their lives are the scoreboard: who''s still calling, who stopped.\n\nNights & events · the spine\nNights & events · the spine Las Vegas · 28 Oct 1966 · ch 1Earl, Carol, Lenny, the recipe lady — and a man crossed out twice Four warm calls. The formula lands.Fifth caller won''t give his name, asked for Hal by a middle name he never uses on air. One sentence: \"Don''t go to the lake, Hal.\" Dial tone. Hal laughs. Sam doesn''t.Close: note from Sam — your sister called, Reno, storage unit. Hal writes a time on the back, crosses it out. Ask her first. Las Vegas · 2 Nov 1966 · ch 2Ruth Hadley — \"Twenty-seven days\" Office name and address off-air. \"We don''t pull people out of their homes on an accusation we know nothing about.\"A later caller recognizes the Boulder Highway office: \"the destination was always going to change.\"Hal doesn''t go home after. Las Vegas · 4 Nov 1966 · ch 3The woman — night one Lenny hangs up. New caller, a woman. No song. \"Tell him not to take Boulder Highway tonight.\"Hal relays it as a joke. Lenny takes Fremont.1:10 AM: a cab is hit head-on on Boulder Highway. Driver Ray Dunning, 38, dead. Lenny is alive. Somebody else isn''t. Nobody''s hands are clean after night one. Las Vegas · 27 Nov 1996 · ch 4Nora opens the boxes The Sands came down last night; the whole town smells like concrete dust. Demolition order for 2201 Industrial Road: 19 Dec.Four boxes. Fifty legal pads. Reel-to-reel. Sam''s call sheets with crossings-out.She plays the first tape. Ruth Hadley''s voice. Slot machines.The studio phone is still on the desk. She lifts it. There''s a tone. Las Vegas · 7 Nov 1966 · ch 5Night four — Carol Carol calls: she''s taking the Stardust job Monday.The woman, after: \"Carol shouldn''t take that job.\" Hal doesn''t relay it. Felt like meddling.Sam, through the glass, writes a word on the sheet and underlines it. Las Vegas · 28 Nov 1996 · ch 6The file that wasn''t there Nora pulls a new folder from box two: Mendez, Carol, 24, missing 14 Dec 1966, Stardust employee lot.It was not in the box last night. She inventoried the box last night.She takes the flyer out of her badge wallet and lays it next to the folder. Same face. Las Vegas · 9 Mar 2026 · ch 7Jo gets two files and a phone Lake Mead unit. Two cold cases, same address, thirty years apart. Supervisor: \"Probably nothing. Clear it.\"Evidence bag: black rotary phone. No cord.She plays tape one on a borrowed deck. Ruth Hadley. Jo has heard that voice on a VHS at Christmas. It''s her great-grandmother. Las Vegas · 12 Nov 1966 · ch 8Night nine — \"Don''t go looking\" Hal has been to Boulder Highway. Met Gabe. Met a man who went to the lake and came back and won''t say what he saw.The woman: \"Her son is already gone. Don''t go looking. Please.\"Hal: \"You keep saying please like you know me.\" — \"I know what you wrote on the back of your sister''s note.\" Las Vegas · 11 Mar 2026 · ch 9The phone rings Jo, alone in the evidence room, 1:50 AM. The bagged phone rings.She picks up. A woman: \"Is this the station?\"Jo: \"…Yeah. This is the station.\" Las Vegas · 3 Dec 1996 · ch 10\"Where are you calling from?\" Nora dials the on-air number for the ninth night. Hal: \"Where are you calling from?\" — \"Las Vegas.\" — \"What year?\"She tells him. He believes her faster than she expected. \"You''ve been reading my pads.\" — \"Every one.\"Somewhere else on the line, faintly, a third breath. Neither of them mentions it. Las Vegas · 23 Nov 1966 · the last nightThanksgiving week Howard Hughes is carried into the Desert Inn on a stretcher. Every reporter in town is at the Desert Inn.Hal signs off early. Writes two words under his own name on the pad: the lake.Leaves the pad on the desk. Takes the coffee.\n\nPlot twists · in reading order\nPlot twists · in reading order 1The warning costsThe woman''s first comment saves Lenny and kills Ray Dunning. She didn''t know. Hal didn''t know. The reader learns the line isn''t free. 2The files changeCarol''s folder appears in Nora''s box overnight. Nora isn''t reading history. She''s reading consequences — of what she said last night. 3\"They''re in a box.\"Hal realizes the woman has read things nobody saw him write. He asks where his pads are. She tells him. 4Two womenOne night \"she\" contradicts herself. Nora has never heard of a Lake Mead barrel. The other voice has. Reader splits the voice in two for the first time. 5Hal dials forwardJo''s phone rings and it isn''t Nora. It''s Hal. He''s figured out the triangle before either woman and he''s calling the far end to ask the only question: \"Did I go to the lake?\" 6Nora''s own fileBox three, bottom: Reyes, N., Det., 30, missing 19 Dec 1996, last seen entering 2201 Industrial Road. She is sitting at 2201 Industrial Road. It is 18 Dec. 7The bloodlineNora asked Hal to stop Carol taking the Stardust job — to save her mother. Hal stayed quiet. Carol took the job, met Tony Reyes, had Nora. Nora exists because Hal ignored her. 8Jo tells the truth\"Yes. You went. Danny Hadley came home. His mother got him back. I''m his granddaughter.\" Hal chooses the trade. He vanishes while the whole city watches a billionaire on a stretcher. 9Sam knewLast call sheet in the box, Sam''s pencil: \"It''s her again. Let her through.\" The screener recognized what she was on night one and opened the door every night after.\n\nEndings · pick one\nEndings · pick one A · The last callNora stays past the 18th for one more call. Dials. Hal answers. She tells him everything she knows — which is now everything.Wrecking ball, 19 Dec. The file was right.2026: Jo plugs the phone in one last time. It rings. A man: \"If you''re still working, God bless you…\" A woman laughs in the background. Jo knows the laugh. It''s hers. B · The quiet oneJo closes both cases \"undetermined,\" takes the phone home, keeps it on the nightstand.It never rings.Last line: she sleeps better than she has in years — which is how she knows he''s done calling. C · The trade undoneJo warns Hal off the lake. He stays. Danny Hadley never comes home. Ruth listens to static.Jo''s phone goes dead mid-sentence. The evidence bag is empty. Her supervisor doesn''t remember assigning her the case.She drives to Henderson. The house her grandfather built isn''t there.\n\nWhy Gen Z reads it · and how the page stays readable\nWhy Gen Z reads it · and how the page stays readable Jo is the way in. 26, voice memos, \"okay,\" a charger reaching for a phone with no port. Every 2026 chapter opens with a voice-memo transcript — timestamped, lowercase, the way she actually talks. That''s the PATTERN group-chat trick, rebuilt for one person alone in an evidence room. Analog is the horror. No caller ID. No screenshots. No way to prove any of it. The three of them have to believe each other or hang up. Every chapter is one night. 12–18 minutes read aloud. Each one ends on a line, not a scene. Built for audio chapters on YouTube like PATTERN. No villain. A cop who closed a file to protect a mother. A host who traded himself for a stranger''s son. A screener who let the impossible call through. Everyone''s complicated. Nobody''s evil. Gen Z doesn''t trust villains anyway. The love story is the warning. Nobody kisses anybody. Nora and Hal talk for nine nights across thirty years and the most intimate thing in the book is a man saying \"they''re in my car\" and a woman saying \"they''re in a box.\" Real and Googleable. Hughes''s stretcher. The Sands implosion. The barrels. St. Thomas under the lake. A reader can check every anchor on their phone and find it''s true — which makes the one thing that isn''t feel true too. The voice stays adult. Short declaratives, no adverbs, dialogue does the work. Gen Z friendly is about the entry point and the pacing — not slang. PATTERN is the slang one; this is the quiet one.\n\nReal events used as furniture\nReal events used as furniture 11 Jun 1938 — Hugh Lord, last resident of St. Thomas, Nevada, rows away as Lake Mead reaches his house. The town goes under. (The lake is where the men are sent. The town is what''s down there.) 1960s — Nevada Test Site underground shots 65 miles north; Vegas hotels sway. Callers mention the shaking. Thanksgiving 1966 — Howard Hughes arrives by train, carried into the Desert Inn on a stretcher, starts buying the Strip. Hal vanishes the same week. 26 Nov 1996 — the Sands is imploded. Vegas is tearing down the sixties. Nora''s building is next. May 2022 — human remains in a barrel surface at Hemenway Harbor as Lake Mead drops; more follow. Cold cases reopen. Jo gets hired. 2022–2026 — record lows; St. Thomas fully walkable. verify at research pass Rule: real events are mentioned by callers, on a bar TV, in a headline. Never explained. Never the plot.\n\nWriting rules\nWriting rules 01Every chapter opens with place + date. Three times, three dates, never blurred. 02One object per time: paper cup with a skin (1966) · county flashlight (1996) · evidence bag (2026). Objects don''t cross timelines until a twist needs them to. 03One light per time: studio red + fluorescent · a flashlight in a dead building · evidence-room white. 04Chapters 1–3: callers only. The woman does not appear until the reader loves at least two of them. 05The woman is never described by voice until twist 4 — only by her words. The reader has to be able to merge two women into one. 06Nobody knows the future. They know files. If a character predicts something that isn''t in a file, that''s a mistake. 07Short declaratives. No adverbs. Dialogue does the work. Kent Haruf, Denis Johnson — not a podcast. 08Don''t invent a date for an unknown day. Leave it unknown. 09Written chapters and proposed events are two different states. This page is 100% proposed.","styleGuide":"Writing rules 01Every chapter opens with place + date. Three times, three dates, never blurred. 02One object per time: paper cup with a skin (1966) · county flashlight (1996) · evidence bag (2026). Objects don''t cross timelines until a twist needs them to. 03One light per time: studio red + fluorescent · a flashlight in a dead building · evidence-room white. 04Chapters 1–3: callers only. The woman does not appear until the reader loves at least two of them. 05The woman is never described by voice until twist 4 — only by her words. The reader has to be able to merge two women into one. 06Nobody knows the future. They know files. If a character predicts something that isn''t in a file, that''s a mistake. 07Short declaratives. No adverbs. Dialogue does the work. Kent Haruf, Denis Johnson — not a podcast. 08Don''t invent a date for an unknown day. Leave it unknown. 09Written chapters and proposed events are two different states. This page is 100% proposed."},"references":"Real events used as furniture 11 Jun 1938 — Hugh Lord, last resident of St. Thomas, Nevada, rows away as Lake Mead reaches his house. The town goes under. (The lake is where the men are sent. The town is what''s down there.) 1960s — Nevada Test Site underground shots 65 miles north; Vegas hotels sway. Callers mention the shaking. Thanksgiving 1966 — Howard Hughes arrives by train, carried into the Desert Inn on a stretcher, starts buying the Strip. Hal vanishes the same week. 26 Nov 1996 — the Sands is imploded. Vegas is tearing down the sixties. Nora''s building is next. May 2022 — human remains in a barrel surface at Hemenway Harbor as Lake Mead drops; more follow. Cold cases reopen. Jo gets hired. 2022–2026 — record lows; St. Thomas fully walkable. verify at research pass Rule: real events are mentioned by callers, on a bar TV, in a headline. Never explained. Never the plot.\nUnverified research anchors from source bible.","garden":{"populated":false,"template":"GOE-1"},"register":[{"date":"31 Oct 2026","project":"THE LAST HOUR","artifact":"story bible v1 (HTML)","author":"Claude","status":"proposal / awaiting go","source":"the-last-hour-bible.html"}]}'::jsonb,'Benji','Import Claude story bible without approving or drafting chapters' WHERE NOT EXISTS(SELECT 1 FROM public.chronicles_dsl_branches WHERE book_id='ab7a1070-1966-4996-8026-000000000101');
